import os
import subprocess

def git_clone(repo_url):
    try:
        subprocess.check_call(['git', 'clone', repo_url])
        print(f"Repository cloned successfully from {repo_url}")
        return True
    except subprocess.CalledProcessError as e:
        print(f"Error cloning repository: {e}")
        return False

def git_create_branch(branch_name, start_point='main', checkout=True):
    try:
        subprocess.check_call(['git', 'branch', branch_name, start_point])
        if checkout:
            subprocess.check_call(['git', 'checkout', branch_name])
        print(f"Branch '{branch_name}' created and checked out.")
        return True
    except subprocess.CalledProcessError as e:
        print(f"Error creating or checking out branch: {e}")
        return False

def fetch_issue(owner, repo, issue_number):
    try:
        import requests
        url = f"https://api.github.com/repos/{owner}/{repo}/issues/{issue_number}"
        response = requests.get(url)
        response.raise_for_status()  # Raise HTTPError for bad responses (4xx or 5xx)
        issue_data = response.json()
        return issue_data['body']
    except requests.exceptions.RequestException as e:
        print(f"Error fetching issue: {e}")
        return None

def read_file(path):
    try:
        with open(path, 'r') as f:
            return f.read()
    except FileNotFoundError:
        print(f"File not found: {path}")
        return None
    except Exception as e:
        print(f"Error reading file: {e}")
        return None

def edit_file(path, old_content, new_content):
    try:
        file_content = read_file(path)
        if file_content is None:
            return False

        new_file_content = file_content.replace(old_content, new_content)

        with open(path, 'w') as f:
            f.write(new_file_content)

        return True
    except Exception as e:
        print(f"Error editing file: {e}")
        return False

def git_commit(message):
    try:
        subprocess.check_call(['git', 'add', '.'])
        subprocess.check_call(['git', 'commit', '-m', message])
        print(f"Changes committed with message: {message}")
        return True
    except subprocess.CalledProcessError as e:
        print(f"Error committing changes: {e}")
        return False

def git_push(force=False):
    try:
        command = ['git', 'push', 'origin', 'HEAD']
        if force:
            command.append('--force')
        subprocess.check_call(command)
        print("Changes pushed to origin.")
        return True
    except subprocess.CalledProcessError as e:
        print(f"Error pushing changes: {e}")
        return False

def create_pr(owner, repo, head_branch, base_branch, title, body):
    import requests
    url = "https://api.github.com/repos/{owner}/{repo}/pulls".format(owner=owner, repo=repo)
    headers = {
